$$ [asy]
unitsize(0.3cm);
pair X,Y,O,N,M;
X=(0,8);
O=(0,0);
Y=(13,0);
N=(6,0);
M=(0,4);
path a=X--Y--O--cycle;
path b=M--Y;
draw(a);
draw(X--N);
draw(shift((16,0))*a);
draw(shift((16,0))*b);
for (int i=0; i<2; ++i) {
label("$X$",shift((16*i,0))*X,W);
label("$O$",shift((16*i,0))*O,S);
